function validSave(s){return s&&s.version===1&&s.hero&&Number.isFinite(s.hero.x)&&s.party?.length===3&&s.party.every(p=>Number.isFinite(p.hp)&&p.maxHp>0)&&Array.isArray(s.shrines)&&Array.isArray(s.defeated)&&Array.isArray(s.chests)&&s.flags&&s.inventory;}
let saved=E.store.get(SAVE,null),S=newState(),mode='title',previousMode='field',checkpoint=null,toastTimer=0,areaTimer=0,lastArea='',hudTimer=0,saveTimer=0,cooldowns={},near=null,dialog=null,menuReturn='field',mousePath=[],poseTime=0,fadeTimer=0,fadeAction=null,battleStarted=null;
